                  <!-- Inner Glowing Liquid Pool -->
                  <path d="M7 19 H25 L26 23 C27 26, 25 28, 21 28 H11 C7 28, 5 26, 6 23 Z" fill="url(#grad_liq_${uid})" stroke="#000" stroke-width="1"/>
