            let currentPower = window.playerStats.artifactCodex[item.trait] || 0;
            let itemPower = item.relicPower !== void 0 ? item.relicPower : 1;
            let poolMatch = window.ARTIFACT_POOL.find((a) => a.trait === item.trait);
            let artTier = poolMatch ? poolMatch.tier || 1 : 1;
