          window.updateShopHeaderWallet();
          let content = document.getElementById("shop-content-panel");
          if (!content) return;
          if (tabKey === "gear") {
            window.renderMarketShop();
          } else if (tabKey === "alchemy") {
            window.renderMysticalShop();
          } else if (tabKey === "sinks") {
            window.renderGoldUpgrades();
          }
