                ctx3.fill();
                ctx3.stroke();
                let capSway = Math.sin(time2 / 160) * (1.8 + swayWeight * 2.2);
                let foldTipX = -13 + capSway;
                let foldTipY = -12 + bounce;
                ctx3.fillStyle = coatColor;
                ctx3.beginPath();
                ctx3.moveTo(-3, -25 + bounce);
