          let activeTree = window.SKILL_TREE_DATA[activeTreeId];
          if (!activeTree) return;
          if (!activeTree.nodes.some((n) => n.id === this.selectedNodeId)) {
            this.selectedNodeId = activeTree.nodes[0].id;
          }
