              c.beginPath();
              c.arc(m.targetX, m.targetY, radius, 0, Math.PI * 2);
              c.stroke();
              c.shadowBlur = 0;
              c.strokeStyle = "rgba(163, 253, 131, 0.6)";
              c.lineWidth = 1.2;
